"""Progressive baseball-IQ question banks used by the learning routes."""


LEVELS = (
    ("foundation", "Foundation", "Core reads and responsibilities"),
    ("competitive", "Competitive", "Multiple reads and game context"),
    ("advanced", "Advanced", "Technical execution and decision tradeoffs"),
)


def field(area, situation, outs, runners, runner_bases, play, question, answers, correct, explanation):
    return {
        "area": area, "situation": situation, "outs": outs, "runners": runners,
        "runner_bases": runner_bases, "play": play, "question": question,
        "answers": answers, "correct": correct, "explanation": explanation,
    }


