def pitch(title, category, count, hitter, pitch_code, zone_x, zone_y, question, answers, correct, explanation):
    return {
        "title": title, "category": category, "count": count, "hitter": hitter,
        "pitch": pitch_code, "zone_x": zone_x, "zone_y": zone_y,
        "question": question, "answers": answers, "correct": correct,
        "explanation": explanation,
    }


